import CoreGraphics
import Foundation
import ImageIO

/// Completion of one API call: `(value, errorCode, errorMessage, errorDetails)`. A non-nil `errorCode` marks a
/// failure. Blocks are Dart listeners, so they may be invoked from any thread.
public typealias ResultBlock = (String?, String?, String?, String?) -> Void

private struct PdfError: Error {
    let code: String
    let message: String
}

/// The API Dart calls through the Objective-C runtime (bindings in `lib/src/bindings/`, generated by
/// `dart run tool/ffigen.dart` from `easy_pdf_viewer_c/easy_pdf_viewer_api.h`, which must match this class selector
/// for selector). Work runs on a serial background queue and answers each callback exactly once.
@objc(EasyPdfViewerApi)
public final class EasyPdfViewerApi: NSObject {
    private static let directory = "EasyPdfViewer"
    private static let workerQueue = DispatchQueue(label: "uz.plugin.easy_pdf_viewer.worker", qos: .userInitiated)
    // Only touched on workerQueue.
    private static var fileName = ""

    @objc public static func getNumberOfPages(_ filePath: String, clearCacheDir: Bool, callback: @escaping ResultBlock) {
        run(callback) {
            let document = try openDocument(filePath)
            let dir = try cacheDirectory()
            if clearCacheDir { removeCache() }
            do {
                try FileManager.default.createDirectory(atPath: dir, withIntermediateDirectories: true)
            } catch {
                throw PdfError(code: "IO_ERROR", message: "Cannot create cache directory: \(error)")
            }
            fileName = UUID().uuidString
            NSLog("[EasyPdfViewerPlugin] File has \(document.numberOfPages) pages")
            return "\(document.numberOfPages)"
        }
    }

    @objc public static func getPage(_ filePath: String, pageNumber: Int, callback: @escaping ResultBlock) {
        run(callback) { try renderPage(filePath, pageNumber: pageNumber) }
    }

    @objc public static func clearCacheDir(_ callback: @escaping ResultBlock) {
        run(callback) {
            removeCache()
            return nil
        }
    }

    private static func run(_ callback: @escaping ResultBlock, _ work: @escaping () throws -> String?) {
        workerQueue.async {
            do {
                callback(try work(), nil, nil, nil)
            } catch let error as PdfError {
                callback(nil, error.code, error.message, nil)
            } catch {
                callback(nil, "UNKNOWN", "PDF operation failed", "\(error)")
            }
        }
    }

    private static func cacheDirectory() throws -> String {
        let paths = NSSearchPathForDirectoriesInDomains(.cachesDirectory, .userDomainMask, true)
        guard let cacheDir = paths.first else { throw PdfError(code: "IO_ERROR", message: "No caches directory") }
        return (cacheDir as NSString).appendingPathComponent(directory)
    }

    private static func removeCache() {
        guard let dir = try? cacheDirectory(), FileManager.default.fileExists(atPath: dir) else { return }
        NSLog("[EasyPdfViewerPlugin] Removing old documents cache")
        do {
            try FileManager.default.removeItem(atPath: dir)
        } catch {
            NSLog("Clear directory error: \(error)")
        }
    }

    private static func openDocument(_ path: String) throws -> CGPDFDocument {
        guard let url = resolveURL(path), let document = CGPDFDocument(url as CFURL) else {
            throw PdfError(code: "IO_ERROR", message: "Cannot open PDF")
        }
        return document
    }

    private static func renderPage(_ path: String, pageNumber: Int) throws -> String {
        let document = try openDocument(path)
        let actualPage = max(1, min(pageNumber, document.numberOfPages))
        let dir = try cacheDirectory()
        do {
            try FileManager.default.createDirectory(atPath: dir, withIntermediateDirectories: true)
        } catch {
            throw PdfError(code: "IO_ERROR", message: "Cannot create cache directory: \(error)")
        }
        guard let page = document.page(at: actualPage) else {
            throw PdfError(code: "INVALID_ARGUMENT", message: "No page \(actualPage)")
        }

        let imageFilePath = (dir as NSString).appendingPathComponent("\(fileName)-\(actualPage).png")
        let sourceRect = page.getBoxRect(.mediaBox)
        let dpi: CGFloat = 300.0 / 72.0
        let width = Int(sourceRect.size.width * dpi)
        let height = Int(sourceRect.size.height * dpi)
        guard width > 0, height > 0 else { throw PdfError(code: "INVALID_ARGUMENT", message: "Empty page") }

        guard let context = CGContext(
            data: nil,
            width: width,
            height: height,
            bitsPerComponent: 8,
            bytesPerRow: 0,
            space: CGColorSpaceCreateDeviceRGB(),
            bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
        ) else { throw PdfError(code: "UNKNOWN", message: "Cannot create bitmap context") }

        context.interpolationQuality = .high
        context.setFillColor(red: 1.0, green: 1.0, blue: 1.0, alpha: 1.0)
        context.fill(CGRect(x: 0, y: 0, width: width, height: height))
        context.scaleBy(x: dpi, y: dpi)
        if sourceRect.origin.x != 0 || sourceRect.origin.y != 0 {
            context.translateBy(x: -sourceRect.origin.x, y: -sourceRect.origin.y)
        }
        context.drawPDFPage(page)

        guard let cgImage = context.makeImage(),
              let destination = CGImageDestinationCreateWithURL(
                URL(fileURLWithPath: imageFilePath) as CFURL, "public.png" as CFString, 1, nil)
        else { throw PdfError(code: "IO_ERROR", message: "Cannot create PNG") }
        CGImageDestinationAddImage(destination, cgImage, nil)
        guard CGImageDestinationFinalize(destination) else {
            throw PdfError(code: "IO_ERROR", message: "Cannot write PNG")
        }
        return imageFilePath
    }

    private static func resolveURL(_ url: String) -> URL? {
        if url.hasPrefix("file:") {
            return URL(string: url)
        }
        return URL(fileURLWithPath: url)
    }
}
